            do {
                try FfiConverterTypeCodexAuthDelegate.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface CodexAuthDelegate: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeCodexAuthDelegate.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface CodexAuthDelegate: handle missing in uniffiClone")
            }
