/**
 * The engine handle held by the app for its whole lifetime.
 */
public protocol PocketEngineProtocol: AnyObject, Sendable {
    
    /**
     * The signed-in Codex account, if any.
     */
    func codexAccount()  -> CodexAccount?
    
    /**
     * Interactive Codex (ChatGPT) sign-in.
     *
     * Binds the localhost callback listener, hands the auth URL to
     * `delegate` for browser presentation, and resolves once the user
     * completes the flow. Tokens persist in the app sandbox through the
     * engine's profile registry.
     */
    func codexLogin(delegate: CodexAuthDelegate) async throws  -> CodexAccount
    
    /**
     * Sign out of Codex, clearing stored tokens.
     */
    func codexLogout() throws 
    
    /**
     * The engine's default Codex model id.
     */
    func defaultCodexModel()  -> String
    
    /**
     * The engine's default model id.
     */
    func defaultModel()  -> String
    
    /**
     * Delete a stored session and its transcript.
     */
    func deleteChatSession(storageDir: String, sessionId: String) async throws 
    
    /**
     * Delete a memory note.
     */
    func deleteMemoryNote(workspaceDir: String, filename: String) async throws 
    
    /**
     * Version of the linked coven-code engine crates.
     */
    func engineVersion()  -> String
    
    /**
     * Copy a stored session at its head under a new id, returning that id.
     */
    func forkChatSession(storageDir: String, sessionId: String) async throws  -> String
    
    /**
     * Local branch names, current branch first.
     */
    func gitBranches(workspacesDir: String, name: String) async throws  -> [String]
    
    /**
     * Switch branches (optionally creating one off HEAD). Existing remote
     * branches get a local tracking branch. Dirty worktrees are refused.
     */
    func gitCheckout(workspacesDir: String, name: String, branch: String, create: Bool) async throws  -> GitWorkspaceSummary
    
    /**
     * Clone a repository. `name` defaults to the repo name in the URL.
     */
    func gitClone(workspacesDir: String, url: String, name: String?, credentials: GitCredentials) async throws  -> GitWorkspaceSummary
    
    /**
     * Stage all changes and commit them, returning the short commit id.
     */
    func gitCommitAll(workspacesDir: String, name: String, message: String, authorName: String, authorEmail: String) async throws  -> String
    
    /**
     * Remove a workspace and everything in it.
     */
    func gitDeleteWorkspace(workspacesDir: String, name: String) async throws 
    
    /**
     * All cloned workspaces, sorted by name.
     */
    func gitListWorkspaces(workspacesDir: String) async throws  -> [GitWorkspaceSummary]
    
    /**
     * Fetch origin and fast-forward the current branch. Errors when the
     * histories have diverged instead of attempting a merge.
     */
    func gitPull(workspacesDir: String, name: String, credentials: GitCredentials) async throws  -> GitWorkspaceSummary
    
    /**
     * Push the current branch to origin (sets upstream on first push).
     */
    func gitPush(workspacesDir: String, name: String, credentials: GitCredentials) async throws  -> GitWorkspaceSummary
    
    /**
     * Perform the mandatory `coven.daemon.v1` handshake against
     * `host:port`: fetch `/api/v1/health` and accept only a daemon that
     * speaks the required contract. Pairing and all session traffic gate
     * on a [`DaemonHandshake::Compatible`] result. Never throws.
     */
    func handshakeDaemon(host: String, port: UInt16, timeoutMs: UInt32) async  -> DaemonHandshake
    
    /**
     * Stored sessions, newest first. Async so the SQLite read stays off the
     * caller's thread (UI thread on iOS).
     */
    func listChatSessions(storageDir: String) async throws  -> [ChatSessionSummary]
    
    /**
     * List models available through the Codex provider.
     *
     * Requires a signed-in Codex account; the catalog itself is static.
     */
    func listCodexModels() async throws  -> [PocketModel]
    
    /**
     * Notes in the workspace's memory directory, newest first.
     */
    func listMemoryNotes(workspaceDir: String) async throws  -> [MemoryNote]
    
    /**
     * List models available through the Anthropic provider.
     */
    func listModels(apiKey: String) async throws  -> [PocketModel]
    
    /**
     * Probe a Coven daemon's `/health` endpoint at `host:port` (reached via
     * the user's Tailscale network or SSH tunnel; the daemon's TCP listener
     * itself stays loopback on its host). Never throws — every outcome is a
     * [`DaemonProbeState`] the UI can render directly.
     */
    func probeDaemon(host: String, port: UInt16, timeoutMs: UInt32) async  -> DaemonProbeState
    
    /**
     * The composed AGENTS.md + memdir context a session would inject for
     * this workspace (the memory toggle's preview).
     */
    func projectContext(workspaceDir: String) async throws  -> ProjectContext
    
    /**
     * Full contents of one memory note.
     */
    func readMemoryNote(workspaceDir: String, filename: String) async throws  -> String
    
    /**
     * Pause active persisted goals after a process interruption.
     */
    func reconcileGoals(storageDir: String) async throws  -> [GoalSnapshot]
    
    /**
     * Scrub credential-shaped content from a transcript before sharing.
     * Runs on the blocking pool: transcripts can be large and the pass is
     * regex-heavy.
     */
    func redactSecrets(text: String) async throws  -> RedactionResult
    
    /**
     * Read one page of a remote session's events after `after_seq`.
     */
    func remoteEvents(host: String, port: UInt16, sessionId: String, afterSeq: Int64, limit: UInt32, timeoutMs: UInt32) async throws  -> RemoteEventBatch
    
    /**
     * List familiars on the paired daemon.
     */
    func remoteFamiliars(host: String, port: UInt16, timeoutMs: UInt32) async throws  -> [RemoteFamiliar]
    
    /**
     * Kill a live remote session.
     */
    func remoteKill(host: String, port: UInt16, sessionId: String, timeoutMs: UInt32) async throws 
    
    /**
     * Launch Claude through the paired daemon's host-side CLI login.
     */
    func remoteLaunchSession(host: String, port: UInt16, projectRoot: String, prompt: String, title: String, familiarId: String?, timeoutMs: UInt32) async throws  -> RemoteSession
    
    /**
     * Forward input (a chat turn or an approval keystroke) to a live
     * remote session.
     */
    func remoteSendInput(host: String, port: UInt16, sessionId: String, data: String, timeoutMs: UInt32) async throws 
    
    /**
     * List sessions on the paired daemon. Callers gate on a verified
     * pairing first; this is plain transport.
     */
    func remoteSessions(host: String, port: UInt16, timeoutMs: UInt32) async throws  -> [RemoteSession]
    
    /**
     * Resume a stored session at its head: the full transcript is restored
     * and new turns append to the same record. Provider settings are the
     * caller's current ones, not necessarily those the session started with.
     */
    func resumeChat(provider: PocketProvider, apiKey: String, model: String, effort: String?, workspaceDir: String, permissionMode: ChatPermissionMode, storageDir: String, sessionId: String, injectContext: Bool) async throws  -> ChatSession
    
    /**
     * Start a multi-turn agentic chat session bound to `workspace_dir`.
     *
     * The session runs the engine's query loop with the sandbox-safe
     * file-tool profile (Read/Grep/Glob/Edit/Write/ApplyPatch/BatchEdit/
     * NotebookEdit); process, network, and task tools are excluded at
     * registry build time, and every tool call is contained to the
     * workspace directory. `workspace_dir` must be an absolute path inside
     * the app sandbox; it is created if missing. `permission_mode` gates
     * write tools (see [`ChatPermissionMode`]) and can be changed later via
     * [`ChatSession::set_permission_mode`].
     *
     * With a `storage_dir` (absolute, created if missing) the conversation
     * persists on device and shows up in [`Self::list_chat_sessions`];
     * `None` keeps the session in memory only.
     */
    func startChat(provider: PocketProvider, apiKey: String, model: String, effort: String?, workspaceDir: String, permissionMode: ChatPermissionMode, storageDir: String?, familiar: FamiliarIdentity?, injectContext: Bool) async throws  -> ChatSession
    
    /**
     * Stream a single-turn completion, forwarding deltas to `delegate`.
     *
     * `effort` accepts `"low" | "medium" | "high" | "max"` and maps onto
     * Anthropic extended thinking (see [`effort_params`]). The Codex
     * Responses adapter does not encode a reasoning-effort control at the
     * current engine pin, so effort is a no-op there. `api_key` is only
     * used for Anthropic; Codex authenticates from stored OAuth tokens.
     *
     * Resolves once the stream finishes; terminal state is reported through
     * `on_done` / `on_error` as well so fire-and-forget callers stay correct.
     */
    func streamPrompt(provider: PocketProvider, apiKey: String, model: String, prompt: String, effort: String?, delegate: StreamDelegate) async throws 
    
    /**
     * Create or overwrite a memory note. Filenames must be plain `*.md`
     * names — the memdir lives outside the workspace sandbox and this is
     * its only writer.
     */
    func writeMemoryNote(workspaceDir: String, filename: String, content: String) async throws 
    
}
