    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_coven_pocket_ffi_fn_clone_streamdelegate(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_coven_pocket_ffi_fn_free_streamdelegate(handle, $0) }
    }

    

    
