/**
 * Outcome of the mandatory `coven.daemon.v1` handshake.
 */

public enum DaemonHandshake: Equatable, Hashable {
    
    /**
     * The daemon speaks `coven.daemon.v1`; pairing may proceed.
     */
    case compatible(identity: DaemonIdentity, latencyMs: UInt32
    )
    /**
     * A Coven daemon answered, but with a different protocol version.
     * `reported` is what it offered (or "unversioned" for pre-v1 daemons).
     */
    case versionMismatch(reported: String
    )
    /**
     * TCP connected but the response was not a Coven daemon at all.
     */
    case notADaemon(detail: String
    )
    /**
     * Connection refused — nothing listening (tunnel down, wrong port).
     */
    case refused
    /**
     * No answer in time — wrong host, VPN down, or a firewall drop.
     */
    case timedOut
    /**
     * The hostname did not resolve.
     */
    case unresolvable
    /**
     * Anything else, with the underlying error text.
     */
    case failed(detail: String
    )





}

#if compiler(>=6)
extension DaemonHandshake: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDaemonHandshake: FfiConverterRustBuffer {
    typealias SwiftType = DaemonHandshake

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DaemonHandshake {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .compatible(identity: try FfiConverterTypeDaemonIdentity.read(from: &buf), latencyMs: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 2: return .versionMismatch(reported: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .notADaemon(detail: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .refused
        
        case 5: return .timedOut
        
        case 6: return .unresolvable
        
        case 7: return .failed(detail: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DaemonHandshake, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .compatible(identity,latencyMs):
            writeInt(&buf, Int32(1))
            FfiConverterTypeDaemonIdentity.write(identity, into: &buf)
            FfiConverterUInt32.write(latencyMs, into: &buf)
            
        
        case let .versionMismatch(reported):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reported, into: &buf)
            
        
        case let .notADaemon(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .refused:
            writeInt(&buf, Int32(4))
        
        
        case .timedOut:
            writeInt(&buf, Int32(5))
        
        
        case .unresolvable:
            writeInt(&buf, Int32(6))
        
        
        case let .failed(detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


